package com.example.receipt

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.provider.Telephony
import android.util.Log

class SmsReceiver : BroadcastReceiver() {
    companion object {
        const val TAG = "SmsReceiver"
        const val ACTION_SMS = "com.example.receipt.SMS_RECEIVED"
    }

    override fun onReceive(context: Context?, intent: Intent?) {
        if (intent?.action != Telephony.Sms.Intents.SMS_RECEIVED_ACTION) return
        context ?: return

        val messages = Telephony.Sms.Intents.getMessagesFromIntent(intent)
        for (msg in messages) {
            val sender = msg.displayOriginatingAddress ?: ""
            val body = msg.displayMessageBody ?: ""
            val timestamp = msg.timestampMillis

            Log.d(TAG, "SMS from $sender: $body")

            val broadcastIntent = Intent(ACTION_SMS).apply {
                putExtra("sender", sender)
                putExtra("body", body)
                putExtra("timestamp", timestamp)
            }
            context.sendBroadcast(broadcastIntent)
        }
    }
}

package com.example.receipt

import android.content.BroadcastReceiver
import android.content.ComponentName
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.database.Cursor
import android.net.Uri
import android.os.Build
import android.os.Bundle
import android.provider.Settings
import android.provider.Telephony
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.EventChannel
import io.flutter.plugin.common.MethodChannel

class MainActivity : FlutterActivity() {

    companion object {
        private const val METHOD_CHANNEL = "com.example.receipt/methods"
        private const val NOTIFICATION_EVENT_CHANNEL = "com.example.receipt/notifications"
        private const val SMS_EVENT_CHANNEL = "com.example.receipt/sms"
    }

    private var notificationReceiver: BroadcastReceiver? = null
    private var smsReceiver: BroadcastReceiver? = null

    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)

        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, METHOD_CHANNEL).setMethodCallHandler { call, result ->
            when (call.method) {
                "isNotificationAccessGranted" -> {
                    result.success(isNotificationListenerEnabled())
                }
                "openNotificationAccessSettings" -> {
                    startActivity(Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS))
                    result.success(true)
                }
                "readSmsHistory" -> {
                    val limit = call.argument<Int>("limit") ?: 200
                    val since = call.argument<Long>("since") ?: 0L
                    result.success(readSmsHistory(limit, since))
                }
                else -> result.notImplemented()
            }
        }

        EventChannel(flutterEngine.dartExecutor.binaryMessenger, NOTIFICATION_EVENT_CHANNEL).setStreamHandler(
            object : EventChannel.StreamHandler {
                override fun onListen(arguments: Any?, events: EventChannel.EventSink?) {
                    notificationReceiver = object : BroadcastReceiver() {
                        override fun onReceive(context: Context?, intent: Intent?) {
                            intent ?: return
                            val data = mapOf(
                                "package" to (intent.getStringExtra("package") ?: ""),
                                "title" to (intent.getStringExtra("title") ?: ""),
                                "text" to (intent.getStringExtra("text") ?: ""),
                                "subText" to (intent.getStringExtra("subText") ?: ""),
                                "timestamp" to intent.getLongExtra("timestamp", System.currentTimeMillis())
                            )
                            events?.success(data)
                        }
                    }
                    val filter = IntentFilter(UpiNotificationListener.ACTION_NOTIFICATION)
                    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                        registerReceiver(notificationReceiver, filter, RECEIVER_NOT_EXPORTED)
                    } else {
                        registerReceiver(notificationReceiver, filter)
                    }
                }

                override fun onCancel(arguments: Any?) {
                    notificationReceiver?.let { unregisterReceiver(it) }
                    notificationReceiver = null
                }
            }
        )

        EventChannel(flutterEngine.dartExecutor.binaryMessenger, SMS_EVENT_CHANNEL).setStreamHandler(
            object : EventChannel.StreamHandler {
                override fun onListen(arguments: Any?, events: EventChannel.EventSink?) {
                    smsReceiver = object : BroadcastReceiver() {
                        override fun onReceive(context: Context?, intent: Intent?) {
                            intent ?: return
                            val data = mapOf(
                                "sender" to (intent.getStringExtra("sender") ?: ""),
                                "body" to (intent.getStringExtra("body") ?: ""),
                                "timestamp" to intent.getLongExtra("timestamp", System.currentTimeMillis())
                            )
                            events?.success(data)
                        }
                    }
                    val filter = IntentFilter(SmsReceiver.ACTION_SMS)
                    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                        registerReceiver(smsReceiver, filter, RECEIVER_NOT_EXPORTED)
                    } else {
                        registerReceiver(smsReceiver, filter)
                    }
                }

                override fun onCancel(arguments: Any?) {
                    smsReceiver?.let { unregisterReceiver(it) }
                    smsReceiver = null
                }
            }
        )
    }

    private fun isNotificationListenerEnabled(): Boolean {
        val cn = ComponentName(this, UpiNotificationListener::class.java)
        val flat = Settings.Secure.getString(contentResolver, "enabled_notification_listeners")
        return flat != null && flat.contains(cn.flattenToString())
    }

    private fun readSmsHistory(limit: Int, sinceTimestamp: Long): List<Map<String, Any>> {
        val results = mutableListOf<Map<String, Any>>()
        val uri: Uri = Telephony.Sms.CONTENT_URI
        val projection = arrayOf(
            Telephony.Sms.ADDRESS,
            Telephony.Sms.BODY,
            Telephony.Sms.DATE,
            Telephony.Sms.TYPE,
        )
        val selection = if (sinceTimestamp > 0) "${Telephony.Sms.DATE} > ?" else null
        val selectionArgs = if (sinceTimestamp > 0) arrayOf(sinceTimestamp.toString()) else null

        var cursor: Cursor? = null
        try {
            cursor = contentResolver.query(
                uri, projection, selection, selectionArgs,
                "${Telephony.Sms.DATE} DESC LIMIT $limit"
            )
            cursor?.let {
                while (it.moveToNext()) {
                    val address = it.getString(0) ?: ""
                    val body = it.getString(1) ?: ""
                    val date = it.getLong(2)
                    val type = it.getInt(3)
                    results.add(mapOf(
                        "sender" to address,
                        "body" to body,
                        "timestamp" to date,
                        "type" to type
                    ))
                }
            }
        } finally {
            cursor?.close()
        }
        return results
    }
}

class TransactionRecord {
  final String id;
  final double amount;
  final TransactionType type;
  final String? upiApp;
  final String? upiTransactionId;
  final String? bankReference;
  final String? counterpartyName;
  final String? counterpartyUpiId;
  final String? accountInfo;
  final String? description;
  String? note;
  String tags;
  final double? latitude;
  final double? longitude;
  final String? locationName;
  final String source;
  final String? rawText;
  final String dedupHash;
  final DateTime transactionDate;
  bool synced;
  final DateTime createdAt;
  DateTime updatedAt;

  TransactionRecord({
    required this.id,
    required this.amount,
    required this.type,
    this.upiApp,
    this.upiTransactionId,
    this.bankReference,
    this.counterpartyName,
    this.counterpartyUpiId,
    this.accountInfo,
    this.description,
    this.note,
    this.tags = '',
    this.latitude,
    this.longitude,
    this.locationName,
    required this.source,
    this.rawText,
    required this.dedupHash,
    required this.transactionDate,
    this.synced = false,
    required this.createdAt,
    required this.updatedAt,
  });

  Map<String, dynamic> toMap() {
    return {
      'id': id,
      'amount': amount,
      'transaction_type': type.value,
      'upi_app': upiApp,
      'upi_transaction_id': upiTransactionId,
      'bank_reference': bankReference,
      'counterparty_name': counterpartyName,
      'counterparty_upi_id': counterpartyUpiId,
      'account_info': accountInfo,
      'description': description,
      'note': note,
      'tags': tags,
      'latitude': latitude,
      'longitude': longitude,
      'location_name': locationName,
      'source': source,
      'raw_text': rawText,
      'dedup_hash': dedupHash,
      'transaction_date': transactionDate.toIso8601String(),
      'synced': synced ? 1 : 0,
      'created_at': createdAt.toIso8601String(),
      'updated_at': updatedAt.toIso8601String(),
    };
  }

  factory TransactionRecord.fromMap(Map<String, dynamic> map) {
    return TransactionRecord(
      id: map['id'] as String,
      amount: (map['amount'] as num).toDouble(),
      type: TransactionType.fromValue(map['transaction_type'] as String),
      upiApp: map['upi_app'] as String?,
      upiTransactionId: map['upi_transaction_id'] as String?,
      bankReference: map['bank_reference'] as String?,
      counterpartyName: map['counterparty_name'] as String?,
      counterpartyUpiId: map['counterparty_upi_id'] as String?,
      accountInfo: map['account_info'] as String?,
      description: map['description'] as String?,
      note: map['note'] as String?,
      tags: (map['tags'] as String?) ?? '',
      latitude: (map['latitude'] as num?)?.toDouble(),
      longitude: (map['longitude'] as num?)?.toDouble(),
      locationName: map['location_name'] as String?,
      source: map['source'] as String,
      rawText: map['raw_text'] as String?,
      dedupHash: map['dedup_hash'] as String,
      transactionDate: DateTime.parse(map['transaction_date'] as String),
      synced: map['synced'] == 1 || map['synced'] == true,
      createdAt: DateTime.parse(map['created_at'] as String),
      updatedAt: DateTime.parse(map['updated_at'] as String),
    );
  }

  TransactionRecord copyWith({
    String? note,
    String? tags,
    bool? synced,
    DateTime? updatedAt,
    String? locationName,
    double? latitude,
    double? longitude,
  }) {
    return TransactionRecord(
      id: id,
      amount: amount,
      type: type,
      upiApp: upiApp,
      upiTransactionId: upiTransactionId,
      bankReference: bankReference,
      counterpartyName: counterpartyName,
      counterpartyUpiId: counterpartyUpiId,
      accountInfo: accountInfo,
      description: description,
      note: note ?? this.note,
      tags: tags ?? this.tags,
      latitude: latitude ?? this.latitude,
      longitude: longitude ?? this.longitude,
      locationName: locationName ?? this.locationName,
      source: source,
      rawText: rawText,
      dedupHash: dedupHash,
      transactionDate: transactionDate,
      synced: synced ?? this.synced,
      createdAt: createdAt,
      updatedAt: updatedAt ?? this.updatedAt,
    );
  }

  List<String> get tagList =>
      tags.isEmpty ? [] : tags.split(',').map((t) => t.trim()).where((t) => t.isNotEmpty).toList();

  String get formattedAmount => '₹${amount.toStringAsFixed(2)}';

  String get upiAppDisplayName {
    switch (upiApp) {
      case 'gpay':
        return 'Google Pay';
      case 'phonepe':
        return 'PhonePe';
      case 'paytm':
        return 'Paytm';
      case 'bhim':
        return 'BHIM';
      case 'whatsapp':
        return 'WhatsApp Pay';
      case 'amazon':
        return 'Amazon Pay';
      case 'mobikwik':
        return 'MobiKwik';
      case 'freecharge':
        return 'Freecharge';
      case 'airtel':
        return 'Airtel Payments';
      case 'jio':
        return 'Jio Pay';
      case 'bank_sms':
        return 'Bank SMS';
      default:
        return upiApp ?? 'Unknown';
    }
  }
}

enum TransactionType {
  debit('debit'),
  credit('credit');

  final String value;
  const TransactionType(this.value);

  factory TransactionType.fromValue(String value) {
    return TransactionType.values.firstWhere(
      (e) => e.value == value,
      orElse: () => TransactionType.debit,
    );
  }
}

import 'package:sqflite/sqflite.dart';
import 'package:path/path.dart';
import '../models/transaction_record.dart';

class LocalDatabase {
  static final LocalDatabase _instance = LocalDatabase._internal();
  factory LocalDatabase() => _instance;
  LocalDatabase._internal();

  Database? _db;

  Future<Database> get database async {
    if (_db != null) return _db!;
    _db = await _initDb();
    return _db!;
  }

  Future<Database> _initDb() async {
    final dbPath = await getDatabasesPath();
    final path = join(dbPath, 'upi_tracker.db');

    return await openDatabase(
      path,
      version: 1,
      onCreate: _onCreate,
    );
  }

  Future<void> _onCreate(Database db, int version) async {
    await db.execute('''
      CREATE TABLE transactions (
        id TEXT PRIMARY KEY,
        amount REAL NOT NULL,
        transaction_type TEXT NOT NULL,
        upi_app TEXT,
        upi_transaction_id TEXT,
        bank_reference TEXT,
        counterparty_name TEXT,
        counterparty_upi_id TEXT,
        account_info TEXT,
        description TEXT,
        note TEXT,
        tags TEXT DEFAULT '',
        latitude REAL,
        longitude REAL,
        location_name TEXT,
        source TEXT NOT NULL,
        raw_text TEXT,
        dedup_hash TEXT NOT NULL,
        transaction_date TEXT NOT NULL,
        synced INTEGER DEFAULT 0,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      )
    ''');

    await db.execute('CREATE INDEX idx_dedup ON transactions(dedup_hash)');
    await db.execute('CREATE INDEX idx_date ON transactions(transaction_date)');
    await db.execute('CREATE INDEX idx_synced ON transactions(synced)');
    await db.execute('CREATE INDEX idx_type ON transactions(transaction_type)');
  }

  Future<int> insertTransaction(TransactionRecord record) async {
    final db = await database;
    return db.insert(
      'transactions',
      record.toMap(),
      conflictAlgorithm: ConflictAlgorithm.ignore,
    );
  }

  Future<bool> existsByDedupHash(String dedupHash) async {
    final db = await database;
    final result = await db.query(
      'transactions',
      where: 'dedup_hash = ?',
      whereArgs: [dedupHash],
      limit: 1,
    );
    return result.isNotEmpty;
  }

  Future<List<TransactionRecord>> getAllTransactions({
    String? typeFilter,
    String? appFilter,
    DateTime? fromDate,
    DateTime? toDate,
    String? searchQuery,
    int? limit,
    int? offset,
  }) async {
    final db = await database;
    final where = <String>[];
    final args = <dynamic>[];

    if (typeFilter != null) {
      where.add('transaction_type = ?');
      args.add(typeFilter);
    }
    if (appFilter != null) {
      where.add('upi_app = ?');
      args.add(appFilter);
    }
    if (fromDate != null) {
      where.add('transaction_date >= ?');
      args.add(fromDate.toIso8601String());
    }
    if (toDate != null) {
      where.add('transaction_date <= ?');
      args.add(toDate.toIso8601String());
    }
    if (searchQuery != null && searchQuery.isNotEmpty) {
      where.add('(counterparty_name LIKE ? OR note LIKE ? OR tags LIKE ? OR description LIKE ?)');
      final q = '%$searchQuery%';
      args.addAll([q, q, q, q]);
    }

    final result = await db.query(
      'transactions',
      where: where.isEmpty ? null : where.join(' AND '),
      whereArgs: args.isEmpty ? null : args,
      orderBy: 'transaction_date DESC',
      limit: limit,
      offset: offset,
    );

    return result.map((m) => TransactionRecord.fromMap(m)).toList();
  }

  Future<TransactionRecord?> getTransactionById(String id) async {
    final db = await database;
    final result = await db.query(
      'transactions',
      where: 'id = ?',
      whereArgs: [id],
      limit: 1,
    );
    if (result.isEmpty) return null;
    return TransactionRecord.fromMap(result.first);
  }

  Future<int> updateTransaction(TransactionRecord record) async {
    final db = await database;
    return db.update(
      'transactions',
      record.toMap(),
      where: 'id = ?',
      whereArgs: [record.id],
    );
  }

  Future<int> deleteTransaction(String id) async {
    final db = await database;
    return db.delete('transactions', where: 'id = ?', whereArgs: [id]);
  }

  Future<List<TransactionRecord>> getUnsyncedTransactions() async {
    final db = await database;
    final result = await db.query(
      'transactions',
      where: 'synced = 0',
      orderBy: 'created_at ASC',
    );
    return result.map((m) => TransactionRecord.fromMap(m)).toList();
  }

  Future<void> markSynced(List<String> ids) async {
    final db = await database;
    final batch = db.batch();
    for (final id in ids) {
      batch.update(
        'transactions',
        {'synced': 1, 'updated_at': DateTime.now().toIso8601String()},
        where: 'id = ?',
        whereArgs: [id],
      );
    }
    await batch.commit(noResult: true);
  }

  Future<Map<String, double>> getSummary({DateTime? fromDate, DateTime? toDate}) async {
    final db = await database;
    final where = <String>[];
    final args = <dynamic>[];

    if (fromDate != null) {
      where.add('transaction_date >= ?');
      args.add(fromDate.toIso8601String());
    }
    if (toDate != null) {
      where.add('transaction_date <= ?');
      args.add(toDate.toIso8601String());
    }

    final whereClause = where.isEmpty ? '' : 'WHERE ${where.join(' AND ')}';

    final debitResult = await db.rawQuery(
      'SELECT COALESCE(SUM(amount), 0) as total FROM transactions $whereClause AND transaction_type = ?',
      [...args, 'debit'],
    );
    final creditResult = await db.rawQuery(
      'SELECT COALESCE(SUM(amount), 0) as total FROM transactions $whereClause AND transaction_type = ?',
      [...args, 'credit'],
    );

    final totalDebit = (debitResult.first['total'] as num?)?.toDouble() ?? 0.0;
    final totalCredit = (creditResult.first['total'] as num?)?.toDouble() ?? 0.0;

    return {
      'total_spent': totalDebit,
      'total_received': totalCredit,
      'net': totalCredit - totalDebit,
    };
  }

  Future<Map<String, double>> getSpendingByApp({DateTime? fromDate, DateTime? toDate}) async {
    final db = await database;
    final where = <String>['transaction_type = ?'];
    final args = <dynamic>['debit'];

    if (fromDate != null) {
      where.add('transaction_date >= ?');
      args.add(fromDate.toIso8601String());
    }
    if (toDate != null) {
      where.add('transaction_date <= ?');
      args.add(toDate.toIso8601String());
    }

    final result = await db.rawQuery(
      'SELECT upi_app, SUM(amount) as total FROM transactions WHERE ${where.join(' AND ')} GROUP BY upi_app ORDER BY total DESC',
      args,
    );

    return {for (var row in result) (row['upi_app'] as String? ?? 'unknown'): (row['total'] as num).toDouble()};
  }

  Future<List<Map<String, dynamic>>> getDailyTotals({
    required DateTime fromDate,
    required DateTime toDate,
  }) async {
    final db = await database;
    final result = await db.rawQuery('''
      SELECT 
        DATE(transaction_date) as date,
        transaction_type,
        SUM(amount) as total
      FROM transactions
      WHERE transaction_date >= ? AND transaction_date <= ?
      GROUP BY DATE(transaction_date), transaction_type
      ORDER BY date ASC
    ''', [fromDate.toIso8601String(), toDate.toIso8601String()]);

    return result;
  }

  Future<int> getTransactionCount() async {
    final db = await database;
    final result = await db.rawQuery('SELECT COUNT(*) as count FROM transactions');
    return (result.first['count'] as int?) ?? 0;
  }
}

import 'package:postgres/postgres.dart';
import 'package:flutter_dotenv/flutter_dotenv.dart';
import '../models/transaction_record.dart';

class RemoteDatabase {
  static final RemoteDatabase _instance = RemoteDatabase._internal();
  factory RemoteDatabase() => _instance;
  RemoteDatabase._internal();

  Connection? _connection;
  bool _tableCreated = false;

  Future<Connection> _getConnection() async {
    if (_connection != null) return _connection!;

    final dbUrl = dotenv.env['DATABASE_URL'];
    if (dbUrl == null || dbUrl.isEmpty) {
      throw Exception('DATABASE_URL not set in .env');
    }

    final endpoint = Endpoint(
      host: _extractHost(dbUrl),
      port: _extractPort(dbUrl),
      database: _extractDatabase(dbUrl),
      username: _extractUsername(dbUrl),
      password: _extractPassword(dbUrl),
    );

    _connection = await Connection.open(
      endpoint,
      settings: ConnectionSettings(sslMode: SslMode.require),
    );

    if (!_tableCreated) {
      await _ensureTables();
      _tableCreated = true;
    }

    return _connection!;
  }

  String _extractHost(String url) {
    final uri = Uri.parse(url.replaceFirst('postgresql://', 'http://'));
    return uri.host;
  }

  int _extractPort(String url) {
    final uri = Uri.parse(url.replaceFirst('postgresql://', 'http://'));
    return uri.port > 0 ? uri.port : 5432;
  }

  String _extractDatabase(String url) {
    final uri = Uri.parse(url.replaceFirst('postgresql://', 'http://'));
    return uri.pathSegments.isNotEmpty ? uri.pathSegments.first : 'neondb';
  }

  String _extractUsername(String url) {
    final uri = Uri.parse(url.replaceFirst('postgresql://', 'http://'));
    return uri.userInfo.split(':').first;
  }

  String _extractPassword(String url) {
    final uri = Uri.parse(url.replaceFirst('postgresql://', 'http://'));
    final parts = uri.userInfo.split(':');
    return parts.length > 1 ? parts.sublist(1).join(':') : '';
  }

  Future<void> _ensureTables() async {
    final conn = _connection!;
    await conn.execute('''
      CREATE TABLE IF NOT EXISTS transactions (
        id TEXT PRIMARY KEY,
        amount DOUBLE PRECISION NOT NULL,
        transaction_type TEXT NOT NULL,
        upi_app TEXT,
        upi_transaction_id TEXT,
        bank_reference TEXT,
        counterparty_name TEXT,
        counterparty_upi_id TEXT,
        account_info TEXT,
        description TEXT,
        note TEXT,
        tags TEXT DEFAULT '',
        latitude DOUBLE PRECISION,
        longitude DOUBLE PRECISION,
        location_name TEXT,
        source TEXT NOT NULL,
        raw_text TEXT,
        dedup_hash TEXT NOT NULL,
        transaction_date TIMESTAMPTZ NOT NULL,
        created_at TIMESTAMPTZ NOT NULL,
        updated_at TIMESTAMPTZ NOT NULL
      )
    ''');

    await conn.execute(
      'CREATE INDEX IF NOT EXISTS idx_remote_dedup ON transactions(dedup_hash)',
    );
    await conn.execute(
      'CREATE INDEX IF NOT EXISTS idx_remote_date ON transactions(transaction_date)',
    );
  }

  Future<void> syncTransactions(List<TransactionRecord> records) async {
    if (records.isEmpty) return;
    final conn = await _getConnection();

    for (final record in records) {
      await conn.execute(
        Sql.named('''
          INSERT INTO transactions (
            id, amount, transaction_type, upi_app, upi_transaction_id,
            bank_reference, counterparty_name, counterparty_upi_id,
            account_info, description, note, tags, latitude, longitude,
            location_name, source, raw_text, dedup_hash, transaction_date,
            created_at, updated_at
          ) VALUES (
            @id, @amount, @transaction_type, @upi_app, @upi_transaction_id,
            @bank_reference, @counterparty_name, @counterparty_upi_id,
            @account_info, @description, @note, @tags, @latitude, @longitude,
            @location_name, @source, @raw_text, @dedup_hash, @transaction_date,
            @created_at, @updated_at
          )
          ON CONFLICT (id) DO UPDATE SET
            note = EXCLUDED.note,
            tags = EXCLUDED.tags,
            updated_at = EXCLUDED.updated_at
        '''),
        parameters: {
          'id': record.id,
          'amount': record.amount,
          'transaction_type': record.type.value,
          'upi_app': record.upiApp,
          'upi_transaction_id': record.upiTransactionId,
          'bank_reference': record.bankReference,
          'counterparty_name': record.counterpartyName,
          'counterparty_upi_id': record.counterpartyUpiId,
          'account_info': record.accountInfo,
          'description': record.description,
          'note': record.note,
          'tags': record.tags,
          'latitude': record.latitude,
          'longitude': record.longitude,
          'location_name': record.locationName,
          'source': record.source,
          'raw_text': record.rawText,
          'dedup_hash': record.dedupHash,
          'transaction_date': record.transactionDate,
          'created_at': record.createdAt,
          'updated_at': record.updatedAt,
        },
      );
    }
  }

  Future<void> close() async {
    await _connection?.close();
    _connection = null;
    _tableCreated = false;
  }
}

import '../models/transaction_record.dart';

class ParsedUpi {
  final double? amount;
  final TransactionType? type;
  final String? counterpartyName;
  final String? counterpartyUpiId;
  final String? upiTransactionId;
  final String? bankReference;
  final String? accountInfo;
  final String? description;
  final String? upiApp;

  ParsedUpi({
    this.amount,
    this.type,
    this.counterpartyName,
    this.counterpartyUpiId,
    this.upiTransactionId,
    this.bankReference,
    this.accountInfo,
    this.description,
    this.upiApp,
  });

  bool get isValid => amount != null && amount! > 0 && type != null;
}

class UpiParser {
  static final _amountPatterns = [
    RegExp(r'[₹Rs\.?\s]*(\d[\d,]*\.?\d{0,2})', caseSensitive: false),
  ];

  static final _upiRefPattern = RegExp(r'(?:UPI\s*(?:Ref|ref|REF)[:\s.#No]*\s*)(\d{10,14})', caseSensitive: false);
  static final _txnIdPattern = RegExp(r'(?:txn\s*(?:id|ID|Id)[:\s]*|Transaction\s*ID[:\s]*)([A-Za-z0-9]+)', caseSensitive: false);
  static final _upiIdPattern = RegExp(r'([a-zA-Z0-9._-]+@[a-zA-Z]+)', caseSensitive: false);
  static final _accountPattern = RegExp(r'(?:A/c|a/c|Ac|ac|account)\s*[*Xx]*(\d{4,})', caseSensitive: false);

  static String? identifyAppFromPackage(String packageName) {
    const mapping = {
      'com.google.android.apps.nbu.paisa.user': 'gpay',
      'net.one97.paytm': 'paytm',
      'com.phonepe.app': 'phonepe',
      'in.org.npci.upiapp': 'bhim',
      'com.whatsapp': 'whatsapp',
      'com.amazon.mShop.android.shopping': 'amazon',
      'com.mobikwik_new': 'mobikwik',
      'com.freecharge.android': 'freecharge',
      'com.myairtel.myairtelapp': 'airtel',
      'com.jio.myjio': 'jio',
    };
    return mapping[packageName];
  }

  static String? identifyAppFromSender(String sender) {
    final s = sender.toUpperCase();
    if (s.contains('GPAY') || s.contains('GOOGLE')) return 'gpay';
    if (s.contains('PAYTM')) return 'paytm';
    if (s.contains('PHONEPE') || s.contains('PHNEPE')) return 'phonepe';
    if (s.contains('BHIM')) return 'bhim';
    if (s.contains('AMAZON')) return 'amazon';
    return null;
  }

  static ParsedUpi parseNotification({
    required String packageName,
    required String title,
    required String text,
  }) {
    final app = identifyAppFromPackage(packageName);
    final combined = '$title $text';
    return _parseText(combined, app ?? 'unknown', isNotification: true);
  }

  static ParsedUpi parseSms({
    required String sender,
    required String body,
  }) {
    final app = identifyAppFromSender(sender) ?? 'bank_sms';
    return _parseText(body, app, isNotification: false);
  }

  static ParsedUpi _parseText(String text, String app, {required bool isNotification}) {
    final type = _detectType(text);
    final amount = _extractAmount(text, type);
    final counterpartyName = _extractCounterparty(text, type);
    final upiId = _extractUpiId(text);
    final upiRef = _extractUpiRef(text);
    final txnId = _extractTxnId(text);
    final account = _extractAccount(text);

    return ParsedUpi(
      amount: amount,
      type: type,
      counterpartyName: counterpartyName,
      counterpartyUpiId: upiId,
      upiTransactionId: txnId ?? upiRef,
      bankReference: upiRef,
      accountInfo: account,
      description: text.length > 200 ? text.substring(0, 200) : text,
      upiApp: app,
    );
  }

  static TransactionType? _detectType(String text) {
    final t = text.toLowerCase();

    final debitKeywords = [
      'paid', 'sent', 'debited', 'debit', 'transferred',
      'payment of', 'spent', 'charged', 'purchase',
      'you paid', 'you sent', 'payment successful',
      'money sent', 'sent to',
    ];
    final creditKeywords = [
      'received', 'credited', 'credit', 'refund',
      'cashback', 'received from', 'money received',
      'you received', 'added to',
    ];

    for (final kw in creditKeywords) {
      if (t.contains(kw)) return TransactionType.credit;
    }
    for (final kw in debitKeywords) {
      if (t.contains(kw)) return TransactionType.debit;
    }
    return null;
  }

  static double? _extractAmount(String text, TransactionType? type) {
    final patterns = [
      RegExp(r'₹\s*([\d,]+\.?\d{0,2})'),
      RegExp(r'Rs\.?\s*([\d,]+\.?\d{0,2})', caseSensitive: false),
      RegExp(r'INR\s*([\d,]+\.?\d{0,2})', caseSensitive: false),
      RegExp(r'Rupees\s*([\d,]+\.?\d{0,2})', caseSensitive: false),
    ];

    for (final pattern in patterns) {
      final match = pattern.firstMatch(text);
      if (match != null) {
        final raw = match.group(1)!.replaceAll(',', '');
        final value = double.tryParse(raw);
        if (value != null && value > 0) return value;
      }
    }
    return null;
  }

  static String? _extractCounterparty(String text, TransactionType? type) {
    final patterns = <RegExp>[];

    if (type == TransactionType.debit) {
      patterns.addAll([
        RegExp(r'(?:paid|sent|transferred)\s+(?:to\s+)?(?:₹[\d,.\s]+\s+)?(?:to\s+)?(.+?)(?:\s*\.|\s*$|\s+on\s+|\s+via\s+|\s+UPI)', caseSensitive: false),
        RegExp(r'to\s+([A-Z][a-zA-Z\s]+?)(?:\s*\.|\s*$|\s+on\s+|\s+via\s+|\s+UPI|\s+using)', caseSensitive: false),
      ]);
    } else if (type == TransactionType.credit) {
      patterns.addAll([
        RegExp(r'(?:received|from)\s+(?:₹[\d,.\s]+\s+)?(?:from\s+)?(.+?)(?:\s*\.|\s*$|\s+on\s+|\s+via\s+|\s+UPI)', caseSensitive: false),
        RegExp(r'from\s+([A-Z][a-zA-Z\s]+?)(?:\s*\.|\s*$|\s+on\s+|\s+via\s+|\s+UPI)', caseSensitive: false),
      ]);
    }

    for (final pattern in patterns) {
      final match = pattern.firstMatch(text);
      if (match != null) {
        var name = match.group(1)?.trim() ?? '';
        name = name.replaceAll(RegExp(r'[₹Rs\.\d,]+'), '').trim();
        if (name.isNotEmpty && name.length < 60) return name;
      }
    }
    return null;
  }

  static String? _extractUpiId(String text) {
    final match = _upiIdPattern.firstMatch(text);
    return match?.group(1);
  }

  static String? _extractUpiRef(String text) {
    final match = _upiRefPattern.firstMatch(text);
    return match?.group(1);
  }

  static String? _extractTxnId(String text) {
    final match = _txnIdPattern.firstMatch(text);
    return match?.group(1);
  }

  static String? _extractAccount(String text) {
    final match = _accountPattern.firstMatch(text);
    if (match != null) return '****${match.group(1)}';
    return null;
  }

  static bool isUpiRelated(String text) {
    final t = text.toLowerCase();
    final keywords = [
      'upi', 'paid', 'received', 'debited', 'credited',
      'payment', 'transaction', '₹', 'rs.', 'inr',
      'gpay', 'phonepe', 'paytm', 'bhim',
    ];
    return keywords.any((kw) => t.contains(kw));
  }
}

import 'dart:convert';
import 'package:crypto/crypto.dart';
import '../database/local_database.dart';
import '../services/upi_parser.dart';

class DedupService {
  final LocalDatabase _localDb;

  DedupService(this._localDb);

  /// Generates a dedup hash based on amount, approximate time, and counterparty.
  /// Transactions within a 10-minute window with same amount and counterparty
  /// are considered duplicates.
  String generateDedupHash(ParsedUpi parsed, DateTime timestamp) {
    if (parsed.upiTransactionId != null && parsed.upiTransactionId!.isNotEmpty) {
      return _hash('txn:${parsed.upiTransactionId}');
    }

    if (parsed.bankReference != null && parsed.bankReference!.isNotEmpty) {
      return _hash('ref:${parsed.bankReference}');
    }

    final roundedTime = DateTime(
      timestamp.year,
      timestamp.month,
      timestamp.day,
      timestamp.hour,
      (timestamp.minute ~/ 10) * 10,
    );
    final amountStr = parsed.amount?.toStringAsFixed(2) ?? '0';
    final counterparty = (parsed.counterpartyName ?? parsed.counterpartyUpiId ?? '')
        .toLowerCase()
        .trim();

    return _hash('amt:$amountStr|time:${roundedTime.toIso8601String()}|party:$counterparty');
  }

  Future<bool> isDuplicate(String dedupHash) async {
    return _localDb.existsByDedupHash(dedupHash);
  }

  String _hash(String input) {
    return md5.convert(utf8.encode(input)).toString();
  }
}

