  Widget _buildPeriodChip(int days, String label) {
    final selected = _selectedDays == days;
    return FilterChip(
      selected: selected,
      label: Text(label, style: const TextStyle(fontSize: 12)),
      onSelected: (_) {
        setState(() => _selectedDays = days);
