import 'dart:async';
import 'dart:convert';
import 'dart:math' as math;

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart' show rootBundle;

/// Lightweight on-device spam classifier.
///
/// Implements Logistic Regression over a TF-IDF (1-2 gram) feature space.
/// Weights are trained offline in `scripts/train_spam_filter.py` and shipped
/// as `assets/spam_model.json`. Inference is pure Dart — no native deps, no
/// ML runtime. A prediction takes well under a millisecond.
///
/// Preprocessing MUST stay byte-identical to the Python training script.
/// See `spam_filter_preprocess_test.dart` for the guard-rails.
class SpamFilter {
  SpamFilter._();
  static final SpamFilter instance = SpamFilter._();

  /// `<token> -> feature index`. Populated on load.
  Map<String, int> _vocab = const {};

  /// Aligned float vectors of length `V`.
  List<double> _idf = const [];
  List<double> _weights = const [];
  double _bias = 0.0;
  double _defaultThreshold = 0.85;
  bool _loaded = false;
  Completer<void>? _loading;

  bool get isLoaded => _loaded;
  double get defaultThreshold => _defaultThreshold;
  int get vocabSize => _vocab.length;

  /// Loads model weights from the bundled asset. Safe to call multiple times;
  /// concurrent calls share a single in-flight load.
  Future<void> load({String assetPath = 'assets/spam_model.json'}) async {
    if (_loaded) return;
    if (_loading != null) return _loading!.future;
    final completer = Completer<void>();
    _loading = completer;
    try {
      final raw = await rootBundle.loadString(assetPath);
      _loadFromJsonString(raw);
      _loaded = true;
      completer.complete();
    } catch (e, s) {
      // Fail open — never block the transaction pipeline on a missing asset.
      debugPrint('SpamFilter: failed to load model ($e). Fail-open enabled.\n$s');
      _vocab = const {};
      _idf = const [];
      _weights = const [];
      _loaded = false;
      completer.complete();
    } finally {
      _loading = null;
    }
  }

  @visibleForTesting
  void loadFromJsonStringForTest(String jsonStr) {
    _loadFromJsonString(jsonStr);
    _loaded = true;
  }

  void _loadFromJsonString(String raw) {
    final obj = json.decode(raw) as Map<String, dynamic>;
    final vocab = (obj['vocab'] as Map).cast<String, dynamic>();
    final idf = (obj['idf'] as List).cast<num>();
    final weights = (obj['weights'] as List).cast<num>();

    if (vocab.length != idf.length || vocab.length != weights.length) {
      throw StateError(
        'SpamFilter: vocab/idf/weights length mismatch '
        '(${vocab.length}/${idf.length}/${weights.length})',
      );
    }

    _vocab = {for (final e in vocab.entries) e.key: (e.value as num).toInt()};
    _idf = idf.map((n) => n.toDouble()).toList(growable: false);
    _weights = weights.map((n) => n.toDouble()).toList(growable: false);
    _bias = (obj['bias'] as num).toDouble();
    _defaultThreshold = (obj['default_threshold'] as num?)?.toDouble() ?? 0.85;
  }

  /// Returns the probability (0..1) that `text` is spam.
  /// Returns 0 when the model isn't loaded (fail-open).
  double spamProbability(String text) {
    if (!_loaded || _vocab.isEmpty) return 0.0;
    final clean = preprocess(text);
    if (clean.isEmpty) return 0.0;

    // Build L2-normalized TF-IDF sparse vector for the 1-2 gram features that
    // appear in our vocab. This matches sklearn's TfidfVectorizer with
    // sublinear_tf=True, norm='l2', use_idf=True.
    final tokens = clean.split(' ').where((t) => t.isNotEmpty).toList(growable: false);

    // Raw term-frequencies keyed by feature index.
    final tf = <int, int>{};

    for (var i = 0; i < tokens.length; i++) {
      final uni = _vocab[tokens[i]];
      if (uni != null) tf[uni] = (tf[uni] ?? 0) + 1;
      if (i + 1 < tokens.length) {
        final bi = _vocab['${tokens[i]} ${tokens[i + 1]}'];
        if (bi != null) tf[bi] = (tf[bi] ?? 0) + 1;
      }
    }
    if (tf.isEmpty) {
      return _sigmoid(_bias);
    }

    // sublinear_tf: tf' = 1 + log(tf), then multiply by idf.
    double norm = 0.0;
    final raw = <int, double>{};
    tf.forEach((idx, count) {
      final v = (1.0 + math.log(count)) * _idf[idx];
      raw[idx] = v;
      norm += v * v;
    });
    norm = math.sqrt(norm);
    if (norm == 0.0) return _sigmoid(_bias);

    double logit = _bias;
    raw.forEach((idx, v) {
      logit += (v / norm) * _weights[idx];
    });
    return _sigmoid(logit);
  }

  /// Convenience: is the text spam at (or above) [threshold]?
  /// Falls back to the model's default threshold when null.
  bool isSpam(String text, {double? threshold}) {
    final t = threshold ?? _defaultThreshold;
    return spamProbability(text) >= t;
  }

  static double _sigmoid(double x) => 1.0 / (1.0 + math.exp(-x));

  // --------------------------------------------------------------------------
  // Preprocessing — MUST mirror scripts/train_spam_filter.py exactly.
  // --------------------------------------------------------------------------

  static final RegExp _urlRe = RegExp(
    r'(?:https?://|www\.)\S+|(?:\b[a-z0-9.-]+\.(?:com|in|org|net|co|io|ly|app|link|me)(?:/\S*)?)',
    caseSensitive: false,
  );
  static final RegExp _amtRe = RegExp(
    r'(?:₹|rs\.?|inr)\s*[\d,]+(?:\.\d{1,2})?',
    caseSensitive: false,
  );
  static final RegExp _longNumRe = RegExp(r'\d{4,}');
  static final RegExp _shortNumRe = RegExp(r'\d+');
  static final RegExp _nonWordRe = RegExp(r'[^a-z0-9<>\s]');
  static final RegExp _wsRe = RegExp(r'\s+');

  /// Canonical preprocessing shared with the Python trainer.
  static String preprocess(String text) {
    if (text.isEmpty) return '';
    var t = text.toLowerCase();
    t = t.replaceAll(_urlRe, ' <url> ');
    t = t.replaceAll(_amtRe, ' <amt> ');
    t = t.replaceAll(_longNumRe, ' <num> ');
    t = t.replaceAll(_shortNumRe, ' <d> ');
    t = t.replaceAll(_nonWordRe, ' ');
    t = t.replaceAll(_wsRe, ' ').trim();
    return t;
  }
}

