import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:receipt/services/spam_filter.dart';
import 'package:receipt/services/upi_parser.dart';

/// Integration test that exercises the full ingestion gate the provider runs:
///   1) UPI keyword pre-filter (cheap)
///   2) SpamFilter ML gate (drops promotional/scam messages)
///   3) UpiParser (amount/type/counterparty extraction)
///
/// This mirrors the exact sequence used in `TransactionProvider._handleSms`
/// and `scanSmsHistory`. The contract under test:
///   - Real bank / UPI SMS → pass the gate and produce a valid parse.
///   - Promotional SMS that look transactional (the user's bug) → blocked.
void main() {
  setUpAll(() {
    final modelPath = File('${Directory.current.path}/assets/spam_model.json');
    expect(modelPath.existsSync(), isTrue);
    SpamFilter.instance.loadFromJsonStringForTest(modelPath.readAsStringSync());
  });

  bool wouldIngest(String sender, String body) {
    if (!UpiParser.isUpiRelated(body)) return false;
    if (SpamFilter.instance.isSpam(body)) return false;
    final parsed = UpiParser.parseSms(sender: sender, body: body);
    return parsed.isValid;
  }

  group('Gate rejects promotional messages', () {
    test('the exact failing user bug — promotional "bonus credited"', () {
      const body =
          'Your account has been credited with a Rs 3,000 bonus, '
          'available for withdrawal within 24 hours. Click: '
          'cutt.ly/StGmXhY1 NowAssignedL1RBPDA';
      // Without the spam filter, the old pipeline would have ingested this
      // because `isUpiRelated` fires on "credited"/"Rs" and the parser can
      // extract an amount. Prove the ML gate stops it.
      expect(UpiParser.isUpiRelated(body), isTrue);
      expect(UpiParser.parseSms(sender: 'VM-BONUS', body: body).isValid, isTrue);
      expect(SpamFilter.instance.isSpam(body), isTrue);
      expect(wouldIngest('VM-BONUS', body), isFalse);
    });

    test('scam / phishing lures are blocked', () {
      const samples = [
        'CONGRATULATIONS! FREE 2GB data is yours! Claim on Airtel Thanks App Now. Hurry i.airtel.in/e/csl_ml_2GB',
        'You have won Rs 5,000 cashback. Click here to claim: http://win.example.com/claim',
        'URGENT: Your KYC has expired. Update OTP at axis-secure.link now to avoid block',
        'You are selected for a Rs 1 crore lottery. Send your bank details to claim@win.co',
      ];
      for (final body in samples) {
        expect(
          wouldIngest('VM-SPAM', body),
          isFalse,
          reason: 'Promotional/scam must be dropped: $body',
        );
      }
    });
  });

  group('Gate passes legit bank and UPI SMS', () {
    test('SBI debit and credit SMS are ingested', () {
      const samples = [
        // The exact formats the parser was tuned for
        'A/C X0587 debited by Rs.50.00 on 11Apr26 trf to M S SURINDER KUM '
            'Refno 602560907627 If not u? call-1800111109 for other '
            'services-18001234-SBI',
        'Dear SBI User, your a/c XX0587 credited by Rs 5,000 on 12Apr26 '
            'transfer from TUMULURI ABHIRAM Ref No 602712800123 -SBI',
      ];
      for (final body in samples) {
        expect(
          wouldIngest('SBIINB', body),
          isTrue,
          reason: 'SBI transactional SMS must reach the parser: $body',
        );
      }
    });

    test('HDFC / ICICI / Axis transactional SMS reach the parser', () {
      const samples = {
        'HDFCBK':
            'Sent Rs.1200.00 From HDFC Bank A/C x1234 To AMAZON PAY On '
                '10/04/26 Ref 204060010123',
        'ICICIB':
            'ICICI Bank Acct XX123 debited for Rs 250.00 on 10-Apr-26; '
                'UPI:604123456789. Call 18002662 for dispute.',
        'AXISBK':
            'INR 450.00 debited A/c no. XX1234 11-04-26 18:45:22 '
                'UPI/P2A/604123456791/ZOMATO. Bal INR 23,456.78.',
      };
      samples.forEach((sender, body) {
        expect(
          wouldIngest(sender, body),
          isTrue,
          reason: '$sender transactional SMS must reach the parser',
        );
      });
    });

    test('GPay / PhonePe / Paytm style notifications are ingested', () {
      const samples = [
        'You paid Rs 250 to Zomato via UPI. UPI transaction ID 604123456800. '
            'From your Google Pay account.',
        'Payment of Rs.250 to swiggy@okhdfcbank successful. PhonePe. '
            'Txn ID T2304100012340',
        'Paytm: Paid Rs 350 to Blinkit via UPI. Order ID OID0987654321',
      ];
      for (final body in samples) {
        expect(
          wouldIngest('VK-GPAY', body),
          isTrue,
          reason: 'UPI-app style message must not be flagged as spam: $body',
        );
      }
    });
  });

  test('spam filter never drops a message the parser accepts as transactional '
      'for real bank corpus', () {
    // Guard-rail: zero false positives on a battery of realistic legit
    // messages. If this ever fails in future retraining, the model is too
    // aggressive and should be loosened (or re-balanced with more HAM data).
    const legit = [
      'A/C X0587 debited by Rs.50.00 on 11Apr26 trf to M S SURINDER KUM Refno 602560907627 If not u? call-1800111109 for other services-18001234-SBI',
      'Dear SBI User, your a/c XX0587 credited by Rs 5,000 on 12Apr26 transfer from TUMULURI ABHIRAM Ref No 602712800123 -SBI',
      'Your A/c XXXXXXX1234 has been debited for Rs.1,250.00 on 10-Apr-26 20:15:03 IST by UPI/P2A/602345678901/NEHA/ICICI Bank. Available bal Rs.12,345.00.',
      'Sent Rs.1200.00 From HDFC Bank A/C x1234 To AMAZON PAY On 10/04/26 Ref 204060010123',
      "You've received Rs 5000.00 in HDFC Bank A/c XX1234 via UPI from SURESH KUMAR on 10-Apr-26 Ref 204060010124",
      'ICICI Bank Acct XX123 debited for Rs 250.00 on 10-Apr-26; UPI:604123456789. Call 18002662 for dispute.',
      'INR 450.00 debited A/c no. XX1234 11-04-26 18:45:22 UPI/P2A/604123456791/ZOMATO. Bal INR 23,456.78.',
      'Kotak: Rs 199 debited from your Ac X0987 via UPI to swiggy@okaxis on 10-Apr-26. UPI Ref 604123456793.',
      'PNB: Rs 350.00 debited from A/c XX1234 on 10-04-26 via UPI. Ref 604123456795. Bal Rs 12350.00.',
      'Union Bank: Rs.500.00 credited to A/c XX1234 on 10-Apr-26 by UPI Ref 604123456797 from PRIYA SINGH.',
      'You paid Rs 250 to Zomato via UPI. UPI transaction ID 604123456800.',
      'Paid Rs 1,200 to Amazon. Google Pay. UPI Ref: 604123456801',
      'You received Rs 500 from Rahul Sharma. Google Pay. UPI Ref: 604123456802',
    ];
    for (final body in legit) {
      final p = SpamFilter.instance.spamProbability(body);
      expect(
        p,
        lessThan(SpamFilter.instance.defaultThreshold),
        reason:
            'Legit bank SMS must not be filtered (p=$p): "$body"',
      );
    }
  });
}

